import { NextRequest, NextResponse } from 'next/server';
import { 
  getCategories, 
  createCategory, 
  CreateCategoryInput 
} from '@/lib/services/category-service';

// GET /api/categories - Get all categories
export async function GET(req: NextRequest) {
  try {
    const categories = await getCategories();
    
    return NextResponse.json({ categories }, { status: 200 });
  } catch (error) {
    console.error('Error in GET /api/categories:', error);
    return NextResponse.json(
      { error: 'Failed to fetch categories' },
      { status: 500 }
    );
  }
}

// POST /api/categories - Create a new category
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    
    // Validate required fields
    if (!body.name || !body.slug || !body.description) {
      return NextResponse.json(
        { error: 'Name, slug, and description are required' },
        { status: 400 }
      );
    }
    
    // Create the category input
    const categoryInput: CreateCategoryInput = {
      name: body.name,
      slug: body.slug,
      description: body.description,
      status: body.status || 'Active'
    };
    
    // Create the category
    const categoryId = await createCategory(categoryInput);
    
    if (!categoryId) {
      return NextResponse.json(
        { error: 'Failed to create category' },
        { status: 500 }
      );
    }
    
    return NextResponse.json({ categoryId }, { status: 201 });
  } catch (error) {
    console.error('Error in POST /api/categories:', error);
    return NextResponse.json(
      { error: 'Failed to create category' },
      { status: 500 }
    );
  }
} 