import { v4 as uuidv4 } from 'uuid';
import { getClient } from '../cassandra';
import { types } from 'cassandra-driver';
import { mockData } from '../mock-data';
import { USE_MOCK_DATA, appLog } from '../config';

// In-memory storage for mock data
let inMemoryCategories = USE_MOCK_DATA ? [...mockData.categories] : [];

export interface Category {
  id: string;
  name: string;
  slug: string;
  description: string;
  status: 'Active' | 'Inactive';
  productCount: number;
  createdAt: Date;
  updatedAt: Date;
}

export interface CreateCategoryInput {
  name: string;
  slug: string;
  description: string;
  status: 'Active' | 'Inactive';
}

export interface UpdateCategoryInput {
  name?: string;
  slug?: string;
  description?: string;
  status?: 'Active' | 'Inactive';
}

// Get all categories
export async function getCategories(): Promise<Category[]> {
  if (USE_MOCK_DATA) {
    appLog('Getting all categories from mock data', 'debug', { count: inMemoryCategories.length });
    return inMemoryCategories;
  }
  
  const client = getClient();
  try {
    const query = `
      SELECT 
        id, name, slug, description, status, product_count, 
        created_at, updated_at
      FROM categories
    `;
    
    const result = await client.execute(query, [], { prepare: true });
    
    return result.rows.map(row => ({
      id: row.id.toString(),
      name: row.name,
      slug: row.slug,
      description: row.description,
      status: row.status,
      productCount: row.product_count,
      createdAt: row.created_at,
      updatedAt: row.updated_at
    }));
  } catch (error) {
    appLog('Error fetching categories', 'error', error);
    return [];
  }
}

// Get a single category by ID
export async function getCategory(id: string): Promise<Category | null> {
  appLog(`Getting category by ID: ${id}`, 'debug');
  
  if (USE_MOCK_DATA) {
    const category = inMemoryCategories.find(c => c.id === id);
    appLog(`Category found in mock data: ${!!category}`, 'debug');
    return category || null;
  }
  
  const client = getClient();
  try {
    const query = `
      SELECT 
        id, name, slug, description, status, product_count, 
        created_at, updated_at
      FROM categories
      WHERE id = ?
    `;
    
    const result = await client.execute(query, [types.Uuid.fromString(id)], { prepare: true });
    
    if (result.rows.length === 0) {
      return null;
    }
    
    const row = result.rows[0];
    return {
      id: row.id.toString(),
      name: row.name,
      slug: row.slug,
      description: row.description,
      status: row.status,
      productCount: row.product_count,
      createdAt: row.created_at,
      updatedAt: row.updated_at
    };
  } catch (error) {
    appLog(`Error fetching category with ID ${id}`, 'error', error);
    return null;
  }
}

// Create a new category
export async function createCategory(input: CreateCategoryInput): Promise<string | null> {
  appLog('Creating new category', 'debug', input);
  const categoryId = uuidv4();
  const now = new Date();
  
  if (USE_MOCK_DATA) {
    const newCategory: Category = {
      id: categoryId,
      name: input.name,
      slug: input.slug,
      description: input.description,
      status: input.status,
      productCount: 0,
      createdAt: now,
      updatedAt: now
    };
    
    inMemoryCategories.push(newCategory);
    appLog(`Category created with ID ${categoryId}`, 'debug');
    return categoryId;
  }
  
  const client = getClient();
  try {
    const query = `
      INSERT INTO categories (
        id, name, slug, description, status, product_count, 
        created_at, updated_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `;
    
    await client.execute(
      query,
      [
        types.Uuid.fromString(categoryId),
        input.name,
        input.slug,
        input.description,
        input.status,
        0, // Initial product count is 0
        now,
        now
      ],
      { prepare: true }
    );
    
    return categoryId;
  } catch (error) {
    appLog('Error creating category', 'error', error);
    return null;
  }
}

// Update an existing category
export async function updateCategory(id: string, input: UpdateCategoryInput): Promise<boolean> {
  const now = new Date();
  appLog(`Updating category with ID: ${id}`, 'debug', input);
  
  if (USE_MOCK_DATA) {
    appLog('Using mock data for update', 'debug');
    const index = inMemoryCategories.findIndex(c => c.id === id);
    appLog(`Category index in mock data: ${index}`, 'debug');
    
    if (index === -1) {
      appLog('Category not found in mock data', 'warning');
      return false;
    }
    
    // Before update
    appLog('Before update', 'debug', inMemoryCategories[index]);
    
    inMemoryCategories[index] = {
      ...inMemoryCategories[index],
      ...(input.name !== undefined && { name: input.name }),
      ...(input.slug !== undefined && { slug: input.slug }),
      ...(input.description !== undefined && { description: input.description }),
      ...(input.status !== undefined && { status: input.status }),
      updatedAt: now
    };
    
    // After update
    appLog('After update', 'debug', inMemoryCategories[index]);
    return true;
  }
  
  const client = getClient();
  try {
    // Build the update query dynamically based on provided fields
    let updateParts = [];
    const params = [];
    
    if (input.name !== undefined) {
      updateParts.push('name = ?');
      params.push(input.name);
    }
    
    if (input.slug !== undefined) {
      updateParts.push('slug = ?');
      params.push(input.slug);
    }
    
    if (input.description !== undefined) {
      updateParts.push('description = ?');
      params.push(input.description);
    }
    
    if (input.status !== undefined) {
      updateParts.push('status = ?');
      params.push(input.status);
    }
    
    // Always update the updated_at timestamp
    updateParts.push('updated_at = ?');
    params.push(now);
    
    // Add the ID as the last parameter
    params.push(types.Uuid.fromString(id));
    
    const query = `
      UPDATE categories
      SET ${updateParts.join(', ')}
      WHERE id = ?
    `;
    
    await client.execute(query, params, { prepare: true });
    
    return true;
  } catch (error) {
    appLog(`Error updating category with ID ${id}`, 'error', error);
    return false;
  }
}

// Delete a category
export async function deleteCategory(id: string): Promise<boolean> {
  appLog(`Deleting category with ID: ${id}`, 'debug');
  
  if (USE_MOCK_DATA) {
    appLog('Using mock data for delete operation', 'debug');
    appLog(`Categories before delete: ${inMemoryCategories.length}`, 'debug');
    
    const initialLength = inMemoryCategories.length;
    const categoryToDelete = inMemoryCategories.find(c => c.id === id);
    
    if (categoryToDelete) {
      appLog('Found category to delete', 'debug', categoryToDelete);
    } else {
      appLog('Category not found in mock data', 'warning');
    }
    
    inMemoryCategories = inMemoryCategories.filter(c => c.id !== id);
    appLog(`Categories after delete: ${inMemoryCategories.length}`, 'debug');
    
    return inMemoryCategories.length < initialLength;
  }
  
  const client = getClient();
  try {
    const query = 'DELETE FROM categories WHERE id = ?';
    
    await client.execute(query, [types.Uuid.fromString(id)], { prepare: true });
    
    return true;
  } catch (error) {
    appLog(`Error deleting category with ID ${id}`, 'error', error);
    return false;
  }
}

// Update the status of a category
export async function updateCategoryStatus(id: string, status: 'Active' | 'Inactive'): Promise<boolean> {
  appLog(`Updating status of category ${id} to ${status}`, 'debug');
  return updateCategory(id, { status });
}

// Increment the product count for a category
export async function incrementProductCount(id: string): Promise<boolean> {
  if (USE_MOCK_DATA) {
    const category = inMemoryCategories.find(c => c.id === id);
    if (!category) return false;
    
    category.productCount += 1;
    category.updatedAt = new Date();
    
    return true;
  }
  
  const client = getClient();
  try {
    const query = `
      UPDATE categories
      SET product_count = product_count + 1
      WHERE id = ?
    `;
    
    await client.execute(query, [types.Uuid.fromString(id)], { prepare: true });
    
    return true;
  } catch (error) {
    appLog(`Error incrementing product count for category ${id}`, 'error', error);
    return false;
  }
}

// Decrement the product count for a category
export async function decrementProductCount(id: string): Promise<boolean> {
  if (USE_MOCK_DATA) {
    const category = inMemoryCategories.find(c => c.id === id);
    if (!category) return false;
    
    category.productCount = Math.max(0, category.productCount - 1);
    category.updatedAt = new Date();
    
    return true;
  }
  
  const client = getClient();
  try {
    const query = `
      UPDATE categories
      SET product_count = product_count - 1
      WHERE id = ?
    `;
    
    await client.execute(query, [types.Uuid.fromString(id)], { prepare: true });
    
    return true;
  } catch (error) {
    appLog(`Error decrementing product count for category ${id}`, 'error', error);
    return false;
  }
} 