/**
 * Application configuration
 */

// Whether to use mock data instead of real database connections
export const USE_MOCK_DATA = true;

// Whether to show detailed debugging information
export const DEBUG = true;

// Log levels
export const LOG_LEVELS = {
  INFO: 'info',
  WARNING: 'warning',
  ERROR: 'error',
  DEBUG: 'debug'
};

// Logger function for consistent logging
export function appLog(
  message: string,
  level: string = LOG_LEVELS.INFO,
  data?: any
) {
  if (!DEBUG && level === LOG_LEVELS.DEBUG) {
    return;
  }

  const timestamp = new Date().toISOString();
  const prefix = `[${timestamp}] [${level.toUpperCase()}]`;

  if (level === LOG_LEVELS.ERROR) {
    console.error(`${prefix} ${message}`, data || '');
  } else if (level === LOG_LEVELS.WARNING) {
    console.warn(`${prefix} ${message}`, data || '');
  } else {
    console.log(`${prefix} ${message}`, data || '');
  }
} 