import { Client } from 'cassandra-driver';

// Set up global client instance
let client: Client | null = null;

// Create a client connection
export function getClient(): Client {
  if (!client) {
    // Check for environment variables
    const contactPoints = process.env.CASSANDRA_CONTACT_POINTS?.split(',') || ['localhost'];
    const localDataCenter = process.env.CASSANDRA_LOCAL_DATACENTER || 'datacenter1';
    const keyspace = process.env.CASSANDRA_KEYSPACE || 'india_seller';
    const username = process.env.CASSANDRA_USERNAME;
    const password = process.env.CASSANDRA_PASSWORD;

    const authProvider = username && password
      ? { username, password }
      : undefined;

    // Create new client
    client = new Client({
      contactPoints,
      localDataCenter,
      keyspace,
      authProvider,
      protocolOptions: { maxVersion: 4 }
    });
  }

  return client;
}

// Initialize database with required tables
export async function initializeDatabase(): Promise<void> {
  const client = getClient();
  
  try {
    // Create categories table if it doesn't exist
    const categoriesTableQuery = `
      CREATE TABLE IF NOT EXISTS categories (
        id uuid PRIMARY KEY,
        name text,
        slug text,
        description text,
        status text,
        product_count int,
        created_at timestamp,
        updated_at timestamp
      )
    `;
    
    await client.execute(categoriesTableQuery);
    console.log('Database tables initialized successfully');
  } catch (error) {
    console.error('Failed to initialize database tables:', error);
    throw error;
  }
}

// Close the client connection
export async function closeClient(): Promise<void> {
  if (client) {
    await client.shutdown();
    client = null;
  }
} 